151	/// Builds the introspector.
152	#[derive(Default)]
153	struct PagedIntrospectorBuilder {
154	    elements: ElementIntrospectorBuilder<PagedPosition>,
155	    frame_link_targets: FxHashSet<Location>,
156	}
157	
158	impl PagedIntrospectorBuilder {
159	    /// Build a complete introspector with all acceleration structures from a
160	    /// list of top-level pairs.
161	    fn finish(
162	        self,
163	        pages: NonZeroUsize,
164	        page_numberings: Vec<Option<Numbering>>,
165	        page_supplements: Vec<Content>,
166	    ) -> PagedIntrospector {
167	        PagedIntrospector {
168	            elements: self.elements.finalize(),
169	            frame_link_targets: self.frame_link_targets,
170	            pages,
171	            page_numberings,
172	            page_supplements,
173	        }
174	    }
175	
176	    /// Discovers introspectibles in a frame.
177	    fn discover_frame<F>(&mut self, frame: &Frame, ts: Transform, to_pos: &mut F)
178	    where
179	        F: FnMut(Point) -> PagedPosition,
180	    {
181	        for (pos, item) in frame.items() {
182	            match item {
183	                FrameItem::Tag(tag) => {
184	                    self.elements.discover_tag(tag, to_pos(pos.transform(ts)));
185	                }
186	                FrameItem::Group(group) => {
187	                    let ts = ts
188	                        .pre_concat(Transform::translate(pos.x, pos.y))
189	                        .pre_concat(group.transform);
190	
191	                    if let Some(parent) = group.parent {
192	                        self.elements.start_insertion();
193	                        self.discover_frame(&group.frame, ts, to_pos);
194	                        self.elements.end_insertion(parent.location);
195	                    } else {
196	                        self.discover_frame(&group.frame, ts, to_pos);
197	                    }
198	                }
199	                FrameItem::Link(dest, _) => {
200	                    if let Destination::Location(loc) = dest {
201	                        self.frame_link_targets.insert(*loc);
202	                    }
203	                }
204	                FrameItem::Text(..) | FrameItem::Shape(..) | FrameItem::Image(..) => {}
205	            }
206	        }
207	    }
208	}
